import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { reportsService } from '../services/api';
import { BarChart3, FileText, Download, AlertCircle, ShieldCheck, Heart, Zap, Baby } from 'lucide-react';
import toast from 'react-hot-toast';

const REPORT_TYPES = {
  animals_inventory: 'Hayvan Envanteri',
  health_summary: 'Sağlık Özeti',
  production: 'Üretim Raporu',
  financial: 'Finansal Rapor',
  reproduction: 'Üreme Raporu'
};

export default function ReportsPage() {
  const { user } = useAuth();
  const farmId = user?.farm_id;

  const [reportType, setReportType] = useState('animals_inventory');
  const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7));
  const [loading, setLoading] = useState(false);
  const [pdfLoading, setPdfLoading] = useState(false);
  const [reportData, setReportData] = useState(null);

  const handleGenerateReport = async () => {
    if (!farmId) {
      toast.error('Çiftlik bilgisi bulunamadı');
      return;
    }
    if (!reportType || !period) {
      toast.error('Rapor türü ve dönem seçimi gerekli');
      return;
    }

    setLoading(true);
    try {
      const res = await reportsService.generate(farmId, {
        report_type: reportType,
        period: period
      });
      setReportData(res?.data?.data || null);
      toast.success('Rapor başarıyla oluşturuldu');
    } catch (err) {
      toast.error(err.response?.data?.error || 'Rapor oluşturulamadı');
    } finally {
      setLoading(false);
    }
  };

  const handleExportPDF = async () => {
    if (!farmId) {
      toast.error('Çiftlik bilgisi bulunamadı');
      return;
    }
    if (!reportType || !period) {
      toast.error('Rapor türü ve dönem seçimi gerekli');
      return;
    }

    setPdfLoading(true);
    try {
      const res = await reportsService.generatePDF(farmId, {
        report_type: reportType,
        period: period
      });
      
      const blob = new Blob([res.data], { type: 'application/pdf' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `mfk-farm-rapor-${reportType}-${period}.pdf`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      
      toast.success('PDF raporu başarıyla indirildi');
    } catch (err) {
      toast.error(err.response?.data?.error || 'PDF indirilemedi');
    } finally {
      setPdfLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">📊 Raporlama Merkezi</h1>
          <p className="text-sm text-gray-500">Çiftlik performansı, üretim ve finansal analizler</p>
        </div>
      </div>

      {/* Rapor Seçim Kartı */}
      <div className="card border-blue-100 bg-blue-50/10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-2 ml-1">Rapor Türü Seçin</label>
              <div className="grid grid-cols-1 gap-2">
                {Object.entries(REPORT_TYPES).map(([key, label]) => (
                  <button
                    key={key}
                    onClick={() => {
                      setReportType(key);
                      setReportData(null);
                    }}
                    className={`flex items-center gap-3 p-3 rounded-2xl text-sm font-bold transition-all border ${
                      reportType === key 
                      ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-600/20 scale-[1.02]' 
                      : 'bg-white text-gray-600 border-gray-100 hover:border-blue-200'
                    }`}
                  >
                    <div className={`p-2 rounded-xl ${reportType === key ? 'bg-white/20' : 'bg-gray-50'}`}>
                      <FileText className="w-4 h-4" />
                    </div>
                    {label}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-6">
            <div>
              <label className="block text-xs font-bold text-gray-400 uppercase mb-2 ml-1">Rapor Dönemi (Ay / Yıl)</label>
              <input
                type="month"
                value={period}
                onChange={e => setPeriod(e.target.value)}
                className="input-field text-lg font-bold py-3"
              />
            </div>

            <div className="space-y-3 pt-4">
              <button
                onClick={handleGenerateReport}
                disabled={loading}
                className="btn-primary w-full flex items-center justify-center gap-2 py-4 shadow-lg shadow-blue-600/20"
              >
                {loading ? (
                  <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                ) : (
                  <><BarChart3 className="w-5 h-5" /> Raporu Hazırla</>
                )}
              </button>
              <button
                onClick={handleExportPDF}
                disabled={pdfLoading || loading}
                className="btn-secondary w-full flex items-center justify-center gap-2 py-4 bg-white"
              >
                {pdfLoading ? (
                  <div className="w-5 h-5 border-2 border-gray-400 border-t-transparent rounded-full animate-spin" />
                ) : (
                  <><Download className="w-5 h-5" /> PDF Olarak İndir</>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Rapor İçeriği */}
      {reportData && (
        <div className="card animate-in fade-in slide-in-from-bottom-4">
          <div className="flex items-center justify-between mb-8 border-b pb-4">
            <h2 className="text-xl font-black text-gray-900">
              {REPORT_TYPES[reportType]} <span className="text-blue-600 ml-2">({period})</span>
            </h2>
          </div>

          {/* Hayvan Envanteri */}
          {reportType === 'animals_inventory' && reportData.animals && (
            <div className="space-y-8">
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                {[
                  { label: 'Toplam', count: reportData.animals.total ?? 0, bg: '#eff6ff', border: '#dbeafe', text: '#2563eb', textDark: '#1d4ed8' },
                  { label: 'Keçi', count: reportData.animals.by_type?.keci ?? 0, bg: '#ecfdf5', border: '#d1fae5', text: '#059669', textDark: '#047857' },
                  { label: 'Koyun', count: reportData.animals.by_type?.koyun ?? 0, bg: '#fff7ed', border: '#ffedd5', text: '#ea580c', textDark: '#c2410c' },
                  { label: 'Sığır', count: reportData.animals.by_type?.sigir ?? 0, bg: '#fef2f2', border: '#fee2e2', text: '#dc2626', textDark: '#b91c1c' },
                  { label: 'Manda', count: reportData.animals.by_type?.manda ?? 0, bg: '#faf5ff', border: '#f3e8ff', text: '#9333ea', textDark: '#7e22ce' },
                  { label: 'Deve', count: reportData.animals.by_type?.deve ?? 0, bg: '#fffbeb', border: '#fef3c7', text: '#d97706', textDark: '#b45309' },
                ].map((item, i) => (
                  <div key={i} className="card text-center p-4 shadow-none" style={{ backgroundColor: item.bg, borderColor: item.border }}>
                    <p className="text-[10px] font-black uppercase tracking-widest" style={{ color: item.text }}>{item.label}</p>
                    <p className="text-2xl font-black mt-1" style={{ color: item.textDark }}>{item.count}</p>
                  </div>
                ))}
              </div>
              {reportData.animals.by_status && (
                <div className="bg-gray-50/50 p-6 rounded-3xl border border-gray-100">
                  <h3 className="font-bold text-gray-900 mb-4">Durum Dağılımı</h3>
                  <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4">
                    {Object.entries(reportData.animals.by_status).map(([status, count]) => (
                      <div key={status} className="flex items-center justify-between p-4 bg-white rounded-2xl border border-gray-100 shadow-sm">
                        <span className="text-sm font-bold text-gray-500 uppercase">
                          {status === 'active' ? 'Aktif' : status === 'dead' ? 'Ölü' : status === 'sold' ? 'Satılmış' : 'Kayıp'}
                        </span>
                        <span className="text-lg font-black text-gray-900">{count ?? 0}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Sağlık Özeti */}
          {reportType === 'health_summary' && reportData.health && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="card flex items-center gap-4 bg-red-50 border-red-100 p-6 shadow-none">
                  <div className="p-3 bg-red-500 rounded-2xl shadow-lg shadow-red-500/20 text-white">
                    <AlertCircle className="w-6 h-6" />
                  </div>
                  <div>
                    <p className="text-red-600 text-[10px] font-black uppercase tracking-widest">Hastalık Kaydı</p>
                    <p className="text-3xl font-black text-red-900">{reportData.health.by_type?.disease ?? 0}</p>
                  </div>
                </div>
                <div className="card flex items-center gap-4 bg-blue-50 border-blue-100 p-6 shadow-none">
                  <div className="p-3 bg-blue-500 rounded-2xl shadow-lg shadow-blue-500/20 text-white">
                    <ShieldCheck className="w-6 h-6" />
                  </div>
                  <div>
                    <p className="text-blue-600 text-[10px] font-black uppercase tracking-widest">Aşı Kaydı</p>
                    <p className="text-3xl font-black text-blue-900">{reportData.health.by_type?.vaccination ?? 0}</p>
                  </div>
                </div>
              </div>
              {reportData.health.records && reportData.health.records.length > 0 && (
                <div className="bg-white rounded-3xl border border-gray-100 overflow-hidden">
                  <div className="px-6 py-4 border-b bg-gray-50/50">
                    <h3 className="font-bold text-gray-900">Kritik Sağlık Kayıtları</h3>
                  </div>
                  <div className="divide-y divide-gray-100">
                    {reportData.health.records.slice(0, 10).map((r, idx) => (
                      <div key={idx} className="p-4 hover:bg-gray-50 transition-colors flex justify-between items-center">
                        <div className="min-w-0">
                          <p className="font-bold text-gray-900 truncate">{r.description || 'Açıklama belirtilmemiş'}</p>
                          <p className="text-[10px] text-gray-500 font-medium uppercase">{r.record_date} • Hayvan #{r.animal_id}</p>
                        </div>
                        <span className="text-xs font-black text-gray-400 bg-gray-100 px-2 py-1 rounded-lg">#{idx + 1}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Üretim Raporu */}
          {reportType === 'production' && reportData.production && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="card bg-amber-50 border-amber-100 p-8 text-center shadow-none">
                  <p className="text-amber-600 text-[10px] font-black uppercase tracking-widest mb-2">Toplam Süt Üretimi</p>
                  <p className="text-5xl font-black text-amber-900">
                    {Number(reportData.production.total_milk || 0).toLocaleString('tr-TR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} <span className="text-xl">Litre</span>
                  </p>
                </div>
                <div className="card bg-emerald-50 border-emerald-100 p-8 text-center shadow-none">
                  <p className="text-emerald-600 text-[10px] font-black uppercase tracking-widest mb-2">Günlük Ortalama Verim</p>
                  <p className="text-5xl font-black text-emerald-900">
                    {Number(reportData.production.avg_daily || 0).toLocaleString('tr-TR', { minimumFractionDigits: 1, maximumFractionDigits: 1 })} <span className="text-xl">Litre/Gün</span>
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Finansal Rapor */}
          {reportType === 'financial' && reportData.financial && (() => {
            const income = Number(reportData.financial.income) || 0;
            const expense = Number(reportData.financial.expense) || 0;
            const profit = Number(reportData.financial.profit ?? (income - expense));
            return (
              <div className="space-y-6">
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  <div className="card bg-green-50 border-l-8 border-green-500 p-6 shadow-none">
                    <p className="text-green-600 text-[10px] font-black uppercase tracking-widest">Aylık Toplam Gelir</p>
                    <p className="text-3xl font-black text-green-900 mt-1">
                      ₺{income.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </p>
                  </div>
                  <div className="card bg-red-50 border-l-8 border-red-500 p-6 shadow-none">
                    <p className="text-red-600 text-[10px] font-black uppercase tracking-widest">Aylık Toplam Gider</p>
                    <p className="text-3xl font-black text-red-900 mt-1">
                      ₺{expense.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </p>
                  </div>
                  <div className={`card ${profit >= 0 ? 'bg-blue-50 border-blue-500' : 'bg-orange-50 border-orange-500'} border-l-8 p-6 shadow-none`}>
                    <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest">Net Kar / Zarar</p>
                    <p className={`text-3xl font-black mt-1 ${profit >= 0 ? 'text-blue-900' : 'text-orange-900'}`}>
                      ₺{profit.toLocaleString('tr-TR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </p>
                  </div>
                </div>
              </div>
            );
          })()}

          {/* Üreme Raporu */}
          {reportType === 'reproduction' && reportData.reproduction && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="card bg-pink-50 border-pink-100 text-center p-6 shadow-none">
                  <div className="w-12 h-12 bg-pink-500 rounded-full flex items-center justify-center text-white mx-auto mb-3 shadow-lg shadow-pink-500/20">
                    <Heart className="w-6 h-6" />
                  </div>
                  <p className="text-pink-600 text-[10px] font-black uppercase tracking-widest">Kızgınlık Kaydı</p>
                  <p className="text-3xl font-black text-pink-900 mt-1">{reportData.reproduction.estrus_count ?? 0}</p>
                </div>
                <div className="card bg-indigo-50 border-indigo-100 text-center p-6 shadow-none">
                  <div className="w-12 h-12 bg-indigo-500 rounded-full flex items-center justify-center text-white mx-auto mb-3 shadow-lg shadow-indigo-500/20">
                    <Zap className="w-6 h-6" />
                  </div>
                  <p className="text-indigo-600 text-[10px] font-black uppercase tracking-widest">Çiftleştirme</p>
                  <p className="text-3xl font-black text-indigo-900 mt-1">{reportData.reproduction.mating_count ?? 0}</p>
                </div>
                <div className="card bg-amber-50 border-amber-100 text-center p-6 shadow-none">
                  <div className="w-12 h-12 bg-amber-500 rounded-full flex items-center justify-center text-white mx-auto mb-3 shadow-lg shadow-amber-500/20">
                    <Baby className="w-6 h-6" />
                  </div>
                  <p className="text-amber-600 text-[10px] font-black uppercase tracking-widest">Doğum</p>
                  <p className="text-3xl font-black text-amber-900 mt-1">{reportData.reproduction.birth_count ?? 0}</p>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* Bilgi */}
      {!reportData && (
        <div className="card bg-blue-50 border-l-4 border-blue-500">
          <p className="text-blue-700">💡 Rapor türü ve dönemi seçerek "Raporu Hazırla" butonuna tıklayın. Çiftliğinize ait tüm veriler derlenecektir.</p>
        </div>
      )}
    </div>
  );
}
